package runtime

import (
	"encoding/base64"
	"encoding/json"
	"errors"
	"math"
	"reflect"
	"strconv"
	"time"
)

// jsonIdentifier is a type that knows its own identity: a struct, and a type
// with a MarshalJSON, generated by schemagen -- into any package, since the
// method is exported and the runtime is shared -- that a check comparing values
// can reach. Every other value is read by IdentifyAt from its Go kind, which is
// all encoding/json writes it by.
type jsonIdentifier interface {
	SchemagenJSONIdentity(m *jsonValidation) (jsonID, error)
}

// jsonValidation is what one call of Validate shares with the checks and the
// values below it: the identities of the elements of every array whose
// uniqueItems was checked, or is about to be, keyed by the array.
//
// The check of an array reads its elements' identities, which the check of the
// array holding it computed on its way through -- so each element's identity
// is computed once however deeply the arrays nest, where each level computing
// its own read the whole subtree again, and a check at every level of a
// recursive document was quadratic in its depth. What the table relies on is
// that a value does not change during one call of Validate.
//
// A jsonValidation with tree set reads trees rather than identities: the value
// as encoding/json decodes the JSON it writes into an any -- map[string]any,
// []any, string, bool, nil, and a float64 or json.Number -- read off the value
// by the same functions and the same rules, each leaving its tree on trees for
// the caller to take. It is what a check asks where an identity cannot answer
// for certain: whether two values that share one are equal (see
// jsonTreeEqual). Nothing is written out to read one.
type Validation struct {
	ids   map[jsonArrayKey][]jsonID
	trees []any
	tree  bool
}

// reading reports whether m reads trees.
func (m *jsonValidation) reading() bool { return m != nil && m.tree }

func (m *jsonValidation) push(t any) { m.trees = append(m.trees, t) }

func (m *jsonValidation) pop() any {
	t := m.trees[len(m.trees)-1]
	m.trees = m.trees[:len(m.trees)-1]
	return t
}

// jsonIDNull is the identity of null, or its tree.
func jsonIDNull(m *jsonValidation) (jsonID, error) {
	if m.reading() {
		m.push(nil)
	}
	return jsonIDOfKind(jsonIDNullKind), nil
}

// jsonIDRawIn is jsonIDRawMessage, or the tree of the raw JSON.
func jsonIDRawIn(b []byte, m *jsonValidation) (jsonID, error) {
	if m.reading() {
		t, err := jsonTreeRaw(b, false)
		if err != nil {
			return jsonID{}, err
		}
		m.push(t)
		return jsonID{}, nil
	}
	return jsonIDRawMessage(b)
}

// jsonIDNumberIn is the identity of a number written as text, or its tree:
// jsonIDNumberLiteral's, which refuses a text that is not a number.
func jsonIDNumberIn(n json.Number, m *jsonValidation) (jsonID, error) {
	if m.reading() {
		if n == "" {
			n = "0"
		}
		if !jsonIsNumberLiteral(string(n)) {
			return jsonID{}, errors.New("json: invalid number literal " + strconv.Quote(string(n)))
		}
		m.push(n)
		return jsonID{}, nil
	}
	return jsonIDNumberLiteral(n)
}

// jsonArrayKey is an array by where its elements are: the address of its first,
// as a typed pointer so that arrays of two types never share a key, and its
// length.
type jsonArrayKey struct {
	first any
	n     int
}

// jsonIdentify is the identity function of a position: IdentifyAt for a
// value read by its Go kind, a type's own jsonIdentity, and the container
// helpers below over one of them.
type Identify[T any] func(*T, *Validation) (ID, error)

// jsonIDPtr, jsonIDSlice and jsonIDMap are the identity of a pointer, a slice
// and a map, as encoding/json writes them: null for a nil one, and an object for
// a map. Their type arguments are written out at every call, for the reason the
// decode helpers' are.
func jsonIDPtr[P ~*E, E any](p P, m *jsonValidation, f Identify[E]) (jsonID, error) {
	if p == nil {
		return jsonIDNull(m)
	}
	return f(p, m)
}

func jsonIDSlice[S ~[]E, E any](s S, m *jsonValidation, f Identify[E]) (jsonID, error) {
	if s == nil {
		return jsonIDNull(m)
	}
	if m.reading() {
		t := make([]any, 0, len(s))
		for i := range s {
			if _, err := f(&s[i], m); err != nil {
				return jsonID{}, err
			}
			t = append(t, m.pop())
		}
		m.push(t)
		return jsonID{}, nil
	}
	var a jsonIDArray
	for i := range s {
		id, err := f(&s[i], m)
		if err != nil {
			return jsonID{}, err
		}
		a.add(id)
	}
	return a.id(), nil
}

// jsonIDSliceKept is jsonIDSlice for an array whose uniqueItems check asks for
// its elements' identities: they are kept in m for it, and read back from m
// where a check above already computed them.
func jsonIDSliceKept[S ~[]E, E any](s S, m *jsonValidation, f Identify[E]) (jsonID, error) {
	if s == nil || m.reading() {
		return jsonIDSlice(s, m, f)
	}
	ids, _, err := jsonIDsOf(s, m, f)
	if err != nil {
		return jsonID{}, err
	}
	var a jsonIDArray
	for _, id := range ids {
		a.add(id)
	}
	return a.id(), nil
}

func jsonIDMap[M ~map[string]V, V any](mp M, m *jsonValidation, f Identify[V]) (jsonID, error) {
	if mp == nil {
		return jsonIDNull(m)
	}
	o := jsonIDObject{m: m}
	var v V
	for k, x := range mp {
		v = x
		id, err := f(&v, m)
		if err != nil {
			return jsonID{}, err
		}
		o.add(k, id)
	}
	return o.id(), nil
}

// jsonIDsOf is the identity of every element of s, or the index of the first
// that has none and why. With m, what is computed is kept there, and what a
// check above computed is read back.
func jsonIDsOf[S ~[]E, E any](s S, m *jsonValidation, f Identify[E]) ([]jsonID, int, error) {
	if len(s) == 0 {
		return nil, -1, nil
	}
	var key jsonArrayKey
	if m != nil {
		key = jsonArrayKey{first: &s[0], n: len(s)}
		if ids, ok := m.ids[key]; ok {
			return ids, -1, nil
		}
	}
	ids := make([]jsonID, len(s))
	for i := range s {
		id, err := f(&s[i], m)
		if err != nil {
			return nil, i, err
		}
		ids[i] = id
	}
	if m != nil {
		if m.ids == nil {
			m.ids = make(map[jsonArrayKey][]jsonID)
		}
		m.ids[key] = ids
	}
	return ids, -1, nil
}

// jsonFirstDuplicate is the index of the first element of s that is equal to an
// earlier one, or -1, given the elements' identities as f reads them. Two
// elements sharing an identity are confirmed equal by jsonSameValue before they
// are called duplicates, and a collision -- two different values with one
// identity -- is compared against every earlier element that has it, which is
// all it costs.
func jsonFirstDuplicate[S ~[]E, E any](s S, ids []jsonID, f Identify[E]) int {
	if len(ids) < 2 {
		return -1
	}
	if len(ids) <= 8 {
		for j := 1; j < len(ids); j++ {
			for i := 0; i < j; i++ {
				if ids[i] == ids[j] && jsonSameValue(&s[i], &s[j], f) {
					return j
				}
			}
		}
		return -1
	}
	first := make(map[jsonID]int, len(ids))
	for j, id := range ids {
		i, ok := first[id]
		if !ok {
			first[id] = j
			continue
		}
		for k := i; k < j; k++ {
			if ids[k] == id && jsonSameValue(&s[k], &s[j], f) {
				return j
			}
		}
	}
	return -1
}

// jsonSameValue reports whether two values are equal as JSON, for certain: the
// one question an identity answers only almost surely, asked only of two values
// that share one. Their trees are read and compared (see jsonTreeEqual);
// nothing is written out.
func jsonSameValue[T any](x, y *T, f Identify[T]) bool {
	tx, err := jsonTreeOf(x, f)
	if err != nil {
		return false
	}
	ty, err := jsonTreeOf(y, f)
	return err == nil && jsonTreeEqual(tx, ty)
}

// jsonTreeOf reads the tree of the value at p, by the function that reads its
// identity. See jsonValidation.
func jsonTreeOf[T any](p *T, f Identify[T]) (any, error) {
	m := &jsonValidation{tree: true}
	if _, err := f(p, m); err != nil {
		return nil, err
	}
	if len(m.trees) != 1 {
		// Structural: every reading leaves exactly one tree.
		return nil, errors.New("schemagen: reading a value left " + strconv.Itoa(len(m.trees)) + " trees")
	}
	return m.trees[0], nil
}

// jsonMatchesConst reports whether the value at p is one of the values c
// permits, reading it with f. An identity decides only a mismatch: a value whose
// identity is not among c's is not among its values, and one whose identity is
// is read as a tree and compared with the member it shares that identity with,
// so a collision of identities can never admit a value the schema forbids.
func jsonMatchesConst[T any](p *T, f Identify[T], c *jsonConst) (bool, error) {
	id, err := f(p, nil)
	if err != nil {
		return false, err
	}
	if !jsonIDIn(id, c.ids) {
		return false, nil
	}
	t, err := jsonTreeOf(p, f)
	if err != nil {
		return false, err
	}
	for i := range c.ids {
		if c.ids[i] == id && jsonTreeEqual(t, c.trees[i]) {
			return true, nil
		}
	}
	return false, nil
}

// jsonMatchesConstAt is jsonMatchesConst for a value read by its Go kind.
func jsonMatchesConstAt[T any](p *T, c *jsonConst) (bool, error) {
	return jsonMatchesConst(p, IdentifyAt[T], c)
}

// jsonTreeAny is the tree of a value held as an any -- what encoding/json
// decodes the JSON it writes for the value into -- read off the value: a type of
// this package by its jsonIdentity, reading trees, and anything else by its Go
// kind, as jsonIDAny reads an identity.
func jsonTreeAny(v any, m *jsonValidation) (any, error) {
	switch x := v.(type) {
	case nil:
		return nil, nil
	case string:
		return jsonValidString(x), nil
	case bool:
		return x, nil
	case float64:
		if math.IsNaN(x) || math.IsInf(x, 0) {
			return nil, &json.UnsupportedValueError{Str: strconv.FormatFloat(x, 'g', -1, 64)}
		}
		return x, nil
	case json.Number:
		if x == "" {
			return json.Number("0"), nil
		}
		if !jsonIsNumberLiteral(string(x)) {
			return nil, errors.New("json: invalid number literal " + strconv.Quote(string(x)))
		}
		return x, nil
	case []any:
		if x == nil {
			return nil, nil
		}
		out := make([]any, len(x))
		for i := range x {
			t, err := jsonTreeAny(x[i], m)
			if err != nil {
				return nil, err
			}
			out[i] = t
		}
		return out, nil
	case map[string]any:
		if x == nil {
			return nil, nil
		}
		out := make(map[string]any, len(x))
		var renamed map[string]string
		// maporder: files each member under its name, and of members sharing one keeps the greatest key's (jsonTreeKeep), which no order of the loop changes.
		for k, e := range x {
			t, err := jsonTreeAny(e, m)
			if err != nil {
				return nil, err
			}
			if name := jsonValidString(k); jsonTreeKeep(out, &renamed, k, name) {
				out[name] = t
			}
		}
		return out, nil
	case map[string]string:
		if x == nil {
			return nil, nil
		}
		out := make(map[string]any, len(x))
		var renamed map[string]string
		// maporder: files each member under its name, and of members sharing one keeps the greatest key's (jsonTreeKeep), which no order of the loop changes.
		for k, e := range x {
			if name := jsonValidString(k); jsonTreeKeep(out, &renamed, k, name) {
				out[name] = jsonValidString(e)
			}
		}
		return out, nil
	case map[string]json.RawMessage:
		if x == nil {
			return nil, nil
		}
		out := make(map[string]any, len(x))
		var renamed map[string]string
		// maporder: files each member under its name, and of members sharing one keeps the greatest key's (jsonTreeKeep), which no order of the loop changes.
		for k, e := range x {
			t, err := jsonTreeAny(e, m)
			if err != nil {
				return nil, err
			}
			if name := jsonValidString(k); jsonTreeKeep(out, &renamed, k, name) {
				out[name] = t
			}
		}
		return out, nil
	case json.RawMessage:
		if x == nil {
			return nil, nil
		}
		return jsonTreeRaw(x, false)
	case jsonIdentifier:
		return jsonTreeOfIdentifier(x, m)
	}
	rv := reflect.ValueOf(v)
	if rv.Kind() != reflect.Pointer {
		p := reflect.New(rv.Type())
		p.Elem().Set(rv)
		rv = p.Elem()
	}
	return jsonTreeReflect(rv, m)
}

// jsonTreeView is v as the runtime evaluator reads a value: v itself where it is
// already what a decode into an any produces -- or a value read lazily from a
// document, which the evaluator reads a level at a time -- and its tree (see
// jsonTreeAny) wherever it, or anything it holds, is some other Go value: an
// element built in Go, a value of this package's types. A container is copied
// only where something in it is read as a tree.
func jsonTreeView(v any) (any, error) {
	switch x := v.(type) {
	case nil, string, bool, float64, json.Number:
		return v, nil
	case jsonLazy:
		return v, nil
	case []any:
		var out []any
		for i := range x {
			t, err := jsonTreeView(x[i])
			if err != nil {
				return nil, err
			}
			if out == nil && !jsonTreeSame(t, x[i]) {
				out = make([]any, len(x))
				copy(out, x[:i])
			}
			if out != nil {
				out[i] = t
			}
		}
		if out == nil {
			return x, nil
		}
		return out, nil
	case map[string]any:
		var out map[string]any
		// maporder: replaces members under their own keys, and copies the map on the first; which member is first changes only when the copy is taken, not what it holds.
		for k, e := range x {
			t, err := jsonTreeView(e)
			if err != nil {
				return nil, err
			}
			if !jsonTreeSame(t, e) {
				if out == nil {
					out = make(map[string]any, len(x))
					// maporder: copies the map, member for member.
					for k2, e2 := range x {
						out[k2] = e2
					}
				}
				out[k] = t
			}
		}
		if out == nil {
			return x, nil
		}
		return out, nil
	}
	return jsonTreeAny(v, nil)
}

// jsonTreeSame reports whether jsonTreeView handed back v itself: a container
// by its identity, where == would compare what it holds or panic.
func jsonTreeSame(t, v any) bool {
	switch x := v.(type) {
	case []any:
		y, ok := t.([]any)
		return ok && len(x) == len(y) && (len(x) == 0 || &x[0] == &y[0])
	case map[string]any:
		y, ok := t.(map[string]any)
		return ok && reflect.ValueOf(x).UnsafePointer() == reflect.ValueOf(y).UnsafePointer()
	}
	switch t.(type) {
	case []any, map[string]any:
		return false
	}
	return t == v
}

// jsonTreeOfIdentifier reads the tree of a value of this package's.
func jsonTreeOfIdentifier(x jsonIdentifier, m *jsonValidation) (any, error) {
	if !m.reading() {
		m = &jsonValidation{tree: true}
	}
	if _, err := x.SchemagenJSONIdentity(m); err != nil {
		return nil, err
	}
	return m.pop(), nil
}

// jsonTreeReflect is jsonIDReflect for a tree.
func jsonTreeReflect(rv reflect.Value, m *jsonValidation) (any, error) {
	t := rv.Type()
	switch t {
	case jsonNumberType:
		return jsonTreeAny(json.Number(rv.String()), m)
	case jsonRawMessageType:
		if rv.IsNil() {
			return nil, nil
		}
		return jsonTreeRaw(rv.Bytes(), false)
	case jsonTimeType:
		tm := rv.Interface().(time.Time)
		if _, err := jsonIDTime(tm); err != nil {
			return nil, err
		}
		return tm.Format(time.RFC3339Nano), nil
	}
	if rv.CanAddr() && reflect.PointerTo(t).Implements(jsonIdentifierType) {
		return jsonTreeOfIdentifier(rv.Addr().Interface().(jsonIdentifier), m)
	}
	if t.Kind() == reflect.Pointer {
		if rv.IsNil() {
			return nil, nil
		}
		return jsonTreeReflect(rv.Elem(), m)
	}
	addressable := rv.CanAddr()
	if t.Implements(jsonMarshalerType) || addressable && reflect.PointerTo(t).Implements(jsonMarshalerType) {
		return jsonTreeMarshaled(rv)
	}
	if t.Implements(jsonTextMarshalerType) || addressable && reflect.PointerTo(t).Implements(jsonTextMarshalerType) {
		var tm jsonTextMarshaler
		if t.Implements(jsonTextMarshalerType) {
			tm = rv.Interface().(jsonTextMarshaler)
		} else {
			tm = rv.Addr().Interface().(jsonTextMarshaler)
		}
		text, err := tm.MarshalText()
		if err != nil {
			return nil, &json.MarshalerError{Type: t, Err: err}
		}
		return jsonValidString(string(text)), nil
	}
	switch t.Kind() {
	case reflect.Interface:
		if rv.IsNil() {
			return nil, nil
		}
		return jsonTreeAny(rv.Elem().Interface(), m)
	case reflect.Bool:
		return rv.Bool(), nil
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		return json.Number(strconv.FormatInt(rv.Int(), 10)), nil
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Uintptr:
		return json.Number(strconv.FormatUint(rv.Uint(), 10)), nil
	case reflect.Float32, reflect.Float64:
		bits := 64
		if t.Kind() == reflect.Float32 {
			bits = 32
		}
		f := rv.Float()
		if math.IsNaN(f) || math.IsInf(f, 0) {
			return nil, &json.UnsupportedValueError{Str: strconv.FormatFloat(f, 'g', -1, bits)}
		}
		return json.Number(strconv.FormatFloat(f, 'g', -1, bits)), nil
	case reflect.String:
		return jsonValidString(rv.String()), nil
	case reflect.Slice:
		if rv.IsNil() {
			return nil, nil
		}
		if e := t.Elem(); e.Kind() == reflect.Uint8 && !reflect.PointerTo(e).Implements(jsonMarshalerType) && !reflect.PointerTo(e).Implements(jsonTextMarshalerType) {
			return base64.StdEncoding.EncodeToString(rv.Bytes()), nil
		}
		fallthrough
	case reflect.Array:
		out := make([]any, rv.Len())
		for i := range out {
			e, err := jsonTreeReflect(rv.Index(i), m)
			if err != nil {
				return nil, err
			}
			out[i] = e
		}
		return out, nil
	case reflect.Map:
		if rv.IsNil() {
			return nil, nil
		}
	}
	return jsonTreeMarshaled(rv)
}

// jsonTreeMarshaled is jsonIDMarshaled for a tree: what encoding/json writes for
// a value no rule here reads -- another package's type with a MarshalJSON of its
// own, a struct this package did not declare, a map of a type the generator did
// not plan -- decoded.
func jsonTreeMarshaled(rv reflect.Value) (any, error) {
	var v any
	if rv.CanAddr() {
		v = rv.Addr().Interface()
	} else {
		v = rv.Interface()
	}
	b, err := json.Marshal(v)
	if err != nil {
		return nil, err
	}
	return jsonTreeRaw(b, false)
}

// jsonMarshalError is what a check reports for a value whose identity could
// not be read -- one encoding/json cannot write either: encoding/json's own
// words for it, which are the words the check always reported, and err where
// encoding/json has none.
func jsonMarshalError[T any](p *T, err error) error {
	if _, mErr := json.Marshal(*p); mErr != nil {
		return mErr
	}
	return err
}

// jsonMarshalText is the value at p as encoding/json writes it, for the message
// of a check that has already refused it.
func jsonMarshalText[T any](p *T) string {
	b, _ := json.Marshal(*p)
	return string(b)
}

// IdentifyAt is the identity of the value at p, for a value this package
// does not write itself: read from its Go kind, as encoding/json writes it.
// The commonest types are read directly; anything else goes through
// jsonIDReflect.
func IdentifyAt[T any](p *T, m *Validation) (ID, error) {
	if m.reading() {
		if v, ok := any(p).(jsonIdentifier); ok {
			return v.SchemagenJSONIdentity(m)
		}
		t, err := jsonTreeAny(any(*p), m)
		if err != nil {
			return jsonID{}, err
		}
		m.push(t)
		return jsonID{}, nil
	}
	switch v := any(p).(type) {
	case jsonIdentifier:
		return v.SchemagenJSONIdentity(m)
	case *string:
		return jsonIDString(*v), nil
	case **string:
		if *v == nil {
			return jsonIDOfKind(jsonIDNullKind), nil
		}
		return jsonIDString(**v), nil
	case *bool:
		return jsonIDBool(*v), nil
	case *int64:
		return jsonIDInt(*v), nil
	case **int64:
		if *v == nil {
			return jsonIDOfKind(jsonIDNullKind), nil
		}
		return jsonIDInt(**v), nil
	case *int:
		return jsonIDInt(int64(*v)), nil
	case *float64:
		return jsonIDFloat(*v, 64)
	case **float64:
		if *v == nil {
			return jsonIDOfKind(jsonIDNullKind), nil
		}
		return jsonIDFloat(**v, 64)
	case *json.Number:
		return jsonIDNumberLiteral(*v)
	case *json.RawMessage:
		return jsonIDRawMessage(*v)
	case *any:
		return jsonIDAny(*v, m)
	case *[]any:
		return jsonIDAnySlice(*v, m)
	case *map[string]any:
		return jsonIDAnyMap(*v, m)
	case *[]string:
		if *v == nil {
			return jsonIDOfKind(jsonIDNullKind), nil
		}
		var a jsonIDArray
		for _, s := range *v {
			a.add(jsonIDString(s))
		}
		return a.id(), nil
	case *map[string]string:
		if *v == nil {
			return jsonIDOfKind(jsonIDNullKind), nil
		}
		var o jsonIDObject
		// maporder: sums the members, which no order of the loop changes.
		for k, s := range *v {
			o.add(k, jsonIDString(s))
		}
		return o.id(), nil
	case *map[string]json.RawMessage:
		return jsonIDMap(*v, m, IdentifyAt[json.RawMessage])
	case *time.Time:
		return jsonIDTime(*v)
	case **time.Time:
		if *v == nil {
			return jsonIDOfKind(jsonIDNullKind), nil
		}
		return jsonIDTime(**v)
	}
	return jsonIDReflect(reflect.ValueOf(p).Elem(), m)
}

// jsonIDAny is the identity of a value held as an any: what encoding/json
// decodes into one, or whatever a caller put there.
func jsonIDAny(v any, m *jsonValidation) (jsonID, error) {
	if m.reading() {
		t, err := jsonTreeAny(v, m)
		if err != nil {
			return jsonID{}, err
		}
		m.push(t)
		return jsonID{}, nil
	}
	switch x := v.(type) {
	case nil:
		return jsonIDOfKind(jsonIDNullKind), nil
	case string:
		return jsonIDString(x), nil
	case bool:
		return jsonIDBool(x), nil
	case float64:
		return jsonIDFloat(x, 64)
	case json.Number:
		return jsonIDNumberLiteral(x)
	case []any:
		return jsonIDAnySlice(x, m)
	case map[string]any:
		return jsonIDAnyMap(x, m)
	case json.RawMessage:
		return jsonIDRawMessage(x)
	case jsonIdentifier:
		return x.SchemagenJSONIdentity(m)
	}
	rv := reflect.ValueOf(v)
	if rv.Kind() != reflect.Pointer {
		// Copied once, so that a method on its pointer is found where
		// encoding/json, which is handed the value addressable, finds it.
		p := reflect.New(rv.Type())
		p.Elem().Set(rv)
		rv = p.Elem()
	}
	return jsonIDReflect(rv, m)
}

func jsonIDAnySlice(s []any, m *jsonValidation) (jsonID, error) {
	if s == nil {
		return jsonIDOfKind(jsonIDNullKind), nil
	}
	var a jsonIDArray
	for i := range s {
		id, err := jsonIDAny(s[i], m)
		if err != nil {
			return jsonID{}, err
		}
		a.add(id)
	}
	return a.id(), nil
}

func jsonIDAnyMap(obj map[string]any, m *jsonValidation) (jsonID, error) {
	if obj == nil {
		return jsonIDOfKind(jsonIDNullKind), nil
	}
	var o jsonIDObject
	// maporder: sums the members, which no order of the loop changes.
	for k, v := range obj {
		id, err := jsonIDAny(v, m)
		if err != nil {
			return jsonID{}, err
		}
		o.add(k, id)
	}
	return o.id(), nil
}

// jsonTextMarshaler is encoding.TextMarshaler, spelled here so that the
// package need not import encoding for one interface.
type jsonTextMarshaler interface {
	MarshalText() ([]byte, error)
}

var (
	jsonIdentifierType    = reflect.TypeFor[jsonIdentifier]()
	jsonMarshalerType     = reflect.TypeFor[json.Marshaler]()
	jsonTextMarshalerType = reflect.TypeFor[jsonTextMarshaler]()
	jsonNumberType        = reflect.TypeFor[json.Number]()
	jsonRawMessageType    = reflect.TypeFor[json.RawMessage]()
	jsonTimeType          = reflect.TypeFor[time.Time]()
)

// jsonIDReflect is the identity of the value rv holds, by the rules
// encoding/json writes a value of its type by: those of the type's own
// MarshalJSON or MarshalText where it has one, and of its kind where it does
// not.
func jsonIDReflect(rv reflect.Value, m *jsonValidation) (jsonID, error) {
	t := rv.Type()
	switch t {
	case jsonNumberType:
		return jsonIDNumberLiteral(json.Number(rv.String()))
	case jsonRawMessageType:
		return jsonIDRawMessage(rv.Bytes())
	case jsonTimeType:
		return jsonIDTime(rv.Interface().(time.Time))
	}
	if rv.CanAddr() && reflect.PointerTo(t).Implements(jsonIdentifierType) {
		return rv.Addr().Interface().(jsonIdentifier).SchemagenJSONIdentity(m)
	}
	if t.Kind() == reflect.Pointer {
		if rv.IsNil() {
			return jsonIDOfKind(jsonIDNullKind), nil
		}
		return jsonIDReflect(rv.Elem(), m)
	}
	addressable := rv.CanAddr()
	if t.Implements(jsonMarshalerType) || addressable && reflect.PointerTo(t).Implements(jsonMarshalerType) {
		return jsonIDMarshaled(rv)
	}
	if t.Implements(jsonTextMarshalerType) || addressable && reflect.PointerTo(t).Implements(jsonTextMarshalerType) {
		var tm jsonTextMarshaler
		if t.Implements(jsonTextMarshalerType) {
			tm = rv.Interface().(jsonTextMarshaler)
		} else {
			tm = rv.Addr().Interface().(jsonTextMarshaler)
		}
		text, err := tm.MarshalText()
		if err != nil {
			return jsonID{}, &json.MarshalerError{Type: t, Err: err}
		}
		return jsonIDString(string(text)), nil
	}
	switch t.Kind() {
	case reflect.Interface:
		if rv.IsNil() {
			return jsonIDOfKind(jsonIDNullKind), nil
		}
		return jsonIDAny(rv.Elem().Interface(), m)
	case reflect.Bool:
		return jsonIDBool(rv.Bool()), nil
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		return jsonIDInt(rv.Int()), nil
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Uintptr:
		return jsonIDUint(rv.Uint()), nil
	case reflect.Float32:
		return jsonIDFloat(rv.Float(), 32)
	case reflect.Float64:
		return jsonIDFloat(rv.Float(), 64)
	case reflect.String:
		return jsonIDString(rv.String()), nil
	case reflect.Slice:
		if rv.IsNil() {
			return jsonIDOfKind(jsonIDNullKind), nil
		}
		if e := t.Elem(); e.Kind() == reflect.Uint8 && !reflect.PointerTo(e).Implements(jsonMarshalerType) && !reflect.PointerTo(e).Implements(jsonTextMarshalerType) {
			// encoding/json writes a []byte as the base64 of its bytes.
			return jsonIDString(base64.StdEncoding.EncodeToString(rv.Bytes())), nil
		}
		fallthrough
	case reflect.Array:
		var a jsonIDArray
		for i := 0; i < rv.Len(); i++ {
			id, err := jsonIDReflect(rv.Index(i), m)
			if err != nil {
				return jsonID{}, err
			}
			a.add(id)
		}
		return a.id(), nil
	case reflect.Map:
		if rv.IsNil() {
			return jsonIDOfKind(jsonIDNullKind), nil
		}
	}
	// A map whose type the generator did not see -- a map it did see is read by
	// jsonIDMap -- a struct this package did not declare, or a kind
	// encoding/json refuses: what encoding/json writes for it is the only
	// account of its value there is.
	return jsonIDMarshaled(rv)
}

// jsonIDMarshaled is the identity of what encoding/json writes for a value no
// rule here reads: another package's type with a MarshalJSON of its own, or a
// struct this package did not declare.
func jsonIDMarshaled(rv reflect.Value) (jsonID, error) {
	var v any
	if rv.CanAddr() {
		v = rv.Addr().Interface()
	} else {
		v = rv.Interface()
	}
	b, err := json.Marshal(v)
	if err != nil {
		return jsonID{}, err
	}
	return jsonIDRaw(b)
}

// jsonOmitEmptyAt and jsonOmitZeroAt are encoding/json's omitempty and omitzero
// rules, for a member holding nothing this package writes itself: false, 0, a
// nil pointer or interface, and an empty string, slice, map or array are empty;
// a value is zero where its IsZero says so, or, without one, where it is Go's
// zero.
func jsonOmitEmptyAt[T any](p *T) bool {
	rv := reflect.ValueOf(p).Elem()
	switch rv.Kind() {
	case reflect.Array, reflect.Map, reflect.Slice, reflect.String:
		return rv.Len() == 0
	case reflect.Bool:
		return !rv.Bool()
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		return rv.Int() == 0
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Uintptr:
		return rv.Uint() == 0
	case reflect.Float32, reflect.Float64:
		return rv.Float() == 0
	case reflect.Interface, reflect.Pointer:
		return rv.IsNil()
	}
	return false
}

func jsonOmitZeroAt[T any](p *T) bool {
	rv := reflect.ValueOf(p).Elem()
	switch rv.Kind() {
	case reflect.Interface, reflect.Pointer:
		if rv.IsNil() {
			return true
		}
	}
	switch z := any(p).(type) {
	case interface{ IsZero() bool }:
		return z.IsZero()
	}
	return rv.IsZero()
}

// SchemagenJSONIdentity is the identity of a value read lazily from a document
// (see Lazy.jsonDocID), or, reading trees, its tree: the value as encoding/json
// decodes it into an any, every number a float64. It is what makes a Lazy an
// identifier, like the types schemagen generates.
func (l jsonLazy) SchemagenJSONIdentity(m *jsonValidation) (jsonID, error) {
	if m.reading() {
		t, err := jsonTreeRaw(l.d.raw(l.sp), !l.exact)
		if err != nil {
			return jsonID{}, err
		}
		m.push(t)
		return jsonID{}, nil
	}
	return l.jsonDocID()
}
